from common import *
from collections import Counter

def main():
 cases=load(R/'config/CASE_LOCK.json');native=load(R/'metrics/NATIVE_SUMMARY.json');gt=load(R/'metrics/BLENDER_GEOMETRIC_METRICS.json');sel=load(R/'config/SELECTED_FINAL.json');pilot=load(R/'metrics/PILOT_SELECTION.json');N=len(cases);runs=[load(R/'metrics'/(c['name']+'_RUN.json'))for c in cases];by={(x['case'],x['label']):x for x in native};gg={(x['case'],x['label']):x for x in gt};valid=[x for x in gt if x['label']=='FINAL013'and x.get('Dxy_AE_mm')is not None];G=len(valid);actual=sum(x['accepted']>0 and x['maximum_displacement_mm']>1e-8 for x in runs);metricrows=[]
 for tag in ['FINAL011','FINAL012','FINAL013']:
  rows=[x for x in gt if x['label']==tag and x.get('Dxy_AE_mm')is not None];are=np.array([x['Dxy_relative_error']for x in rows]);ae=np.array([x['Dxy_AE_mm']for x in rows]);metricrows.append(dict(label=tag,target_groups=N,numerical_outputs=N,GT_metric_coverage=len(rows),median_ARE=float(np.median(are))if len(are)else None,MAE_mm=float(ae.mean())if len(ae)else None,p95_AE_mm=float(np.quantile(ae,.95))if len(ae)else None,max_AE_mm=float(ae.max())if len(ae)else None))
 table('metrics/MEASUREMENT_AUDIT_SUMMARY.csv',metricrows);save('metrics/MEASUREMENT_AUDIT_SUMMARY.json',metricrows);paired=[]
 for c in cases:
  n=c['name'];a=gg.get((n,'FINAL012'),{});b=gg.get((n,'FINAL013'),{});paired.append(dict(case=n,common_surface_success=a.get('Chamfer_MAE_mm')is not None and b.get('Chamfer_MAE_mm')is not None,delta_Chamfer_013_minus012_mm=b['Chamfer_MAE_mm']-a['Chamfer_MAE_mm']if a.get('Chamfer_MAE_mm')is not None and b.get('Chamfer_MAE_mm')is not None else None,delta_Dxy_AE_013_minus012_mm=b['Dxy_AE_mm']-a['Dxy_AE_mm']if a.get('Dxy_AE_mm')is not None and b.get('Dxy_AE_mm')is not None else None,delta_FIT_IoU=by[n,'FINAL013']['FIT_IoU']-by[n,'FINAL012']['FIT_IoU'],delta_HOLDOUT_IoU=by[n,'FINAL013']['HOLDOUT_IoU']-by[n,'FINAL012']['HOLDOUT_IoU']))
 table('metrics/PAIRED_012_013.csv',paired);save('metrics/PAIRED_012_013.json',paired)
 def val(x):return 'NaN'if x is None else '%.4f'%x if isinstance(x,(float,np.floating))else str(x)
 lines=['# FREE_VERTEX_013 技术报告','',f'完成 {N} 个独立物理组的统一自由顶点实验；本轮最终配置为 **{sel["loss"]}+{sel["optimizer"]}**。选择只使用预注册四例 FIT 指标，留出与 Blender 均未参与。数值输出不等于真实形态恢复。','',f'其中 {actual}/{N} 例产生非零接受更新。最终预测为固定预算的最后接受状态，未挑选最好中间结果。','', '## 核心审阅图','', '[十一例真实Mesh总览](figures/Fig1_Eleven_Actual_Meshes.png) · [五例Ip柄部](figures/Fig2_Five_Ip_Stalk_Comparison.png) · [损失与更新机制](figures/Fig3_Loss_Update_Mechanism.png) · [纯主体最佳刚性对齐](figures/Fig4_Best_Rigid_Body_Comparison.png)','', '## 五个问题','', '1. **G03原先为何难以恢复柄部？** 012固定来源复核：13/100接受，最大位移0.000340796mm；总上限约4.7784mm且从未触发TOTAL_TRUST。293次RING_WORSENING、1231次FULL_FIT_OBJECTIVE，学习率落到1e-5。因此不能把原失败归因为累计位移不足；远轮廓梯度范围、整体方向与Ring接触冲突、先验/深度和接受搜索共同限制更新。新实验的实际梯度及各项隔离对照见下表和图3。','2. **新增损失、优化与范围各有何作用？** 四个损失和O1–O4分别比较，未将所有变化捆绑后归因。见metrics/PILOT_SELECTION.json的逐病例配对差、各臂梯度与拒绝记录。最终选择不代表所有病例均获益；不能以总损失跨臂比较。','3. **是否推广到其他Ip而不损害Is/IIa？** 下列11例同时报告FIT与HOLDOUT、实际毫米位移、接受比例与几何失败；未按类型选择超参数。新增G10/G11为新生成配方等效011起点，不能伪称历史结果。','4. **固定尺度后的形状精度？** 所有011/012/013均使用同一96旋转初值、双向最近表面SE(3)评价；不是旧24初值数字与新数字混比。最佳仅为已搜索候选最佳。完整分布、双向距离、F-score、Dxy、Hmax/H95、最低点/顶部跨度及条件体积见指标表。','5. **剩余误差与路线选择？** 长柄缺失必须同时查看GT到预测覆盖、最低点距离、完整六视图，Dxy/Hmax接近不构成柄部恢复。固定拓扑为球面拓扑，柄也可保持同拓扑，故不能仅凭未恢复宣称拓扑不可能；局部采样/正则、可见性与Ring方向冲突、HERO噪声和轮廓欠约束仍需区分。本轮有限隔离实验不构成否定整条路线或自动切换路线的充分证据。','', '## 逐病例固定分母结果','', '|组|接受/候选|最大位移mm|012FITIoU|013FITIoU|012留出IoU|013留出IoU|013Chamfer mm|013DxyAE mm|','|---|---:|---:|---:|---:|---:|---:|---:|---:|']
 for c,run in zip(cases,runs):
  n=c['name'];a=by[n,'FINAL012'];b=by[n,'FINAL013'];g=gg.get((n,'FINAL013'),{});lines.append('|'+ '|'.join(map(str,[n,str(run['accepted'])+'/'+str(run['attempts']),val(run['maximum_displacement_mm']),val(a['FIT_IoU']),val(b['FIT_IoU']),val(a['HOLDOUT_IoU']),val(b['HOLDOUT_IoU']),val(g.get('Chamfer_MAE_mm')),val(g.get('Dxy_AE_mm'))]))+'|')
 lines+=['','## 全体分母与配对精度审计','','**After Ring-based Metric Recovery and Best 6-DoF Rigid Alignment**。这是姿态差异移除后的形状评价，不是端到端定位精度。作者基底与真实部署基底对应仍为条件评价。Ring固定CAD尺度只恢复/核验，不声称独立预测Ring尺寸。','','|版本|目标|Dxy可评价|中位ARE|MAE mm|p95AE mm|最大AE mm|','|---|---:|---:|---:|---:|---:|---:|']
 for x in metricrows:lines.append('|'+ '|'.join(val(x[k])for k in ['label','target_groups','GT_metric_coverage','median_ARE','MAE_mm','p95_AE_mm','max_AE_mm'])+'|')
 lines+=['','[共同成功组配对比较](metrics/PAIRED_012_013.csv)；对照是011/012共享初值与同一评价程序，不包含历史融合预测回退。缺失/非法实体保持NaN，不以P0体积为真值。','', '|审计项目|必须汇报|','|---|---|',f'|目标组数|{N}，原九例+新增两个独立Ip|',f'|本算法独立成功|数值最终输出{N}/{N}；实际非零接受更新{actual}/{N}，不等于形态正确|',f'|本算法失败|见逐例失败台账；Dxy不可评价{N-G}/{N}保留NaN|','|历史测量值回退|0；011仅为用户指定初始化，012仅作对照|','|失败组及具体原因|[FAILURE_LEDGER.md](FAILURE_LEDGER.md)与每组全部候选记录|',f'|最终统计样本|Dxy仅{G}个独立可评价组，同时明确全体{N}分母；表面/实体各有独立分母|','|是否使用GT选择算法|否；PREREGISTRATION、各臂PREOPT_FREEZE、SELECTED_FINAL、PREDICTIONS_FROZEN_BEFORE_GT和SCALE_LOCK按时间链记录|','', '## 限制与停止','','真实输入不等于相机绝对认证；历史条件标签继续保留。表面支持来自固定图像/Mask/CAD证据，不是解剖GT。推断底盖和未观测背面分别记录；非法或不可靠实体不输出严格3DIoU，以明确命名的容差F-score表面代理补充。离散可见性/最近邻使目标分段可微，有限差分切换完整保留。几何保护使用离散签名样本+实际三角形检查，不能冒称连续非穿透证明。','', '本轮完成后停止，待人工审核，不替换正式主线、不追加损失搜索、不修改DXY。']
 extra=['','## 隔离对照与追加修正','','O3N为初始试跑后的单次步长量纲修正，不冒称最初协议内的预注册臂；在运行前另行冻结并提交。原始臂和失败均保留。固定A3/O3N/1D仅再核验一次，没有GT/留出调参。','', '|类别|臂|四例平均FIT评分变化|改善病例/4|安全/覆盖入选资格|通用改善证据|','|---|---|---:|---:|---|---|']
 for category,key in [('损失','loss_comparison'),('优化器','optimizer_comparison')]:
  for x in pilot[key]:extra.append('|'+ '|'.join([category,x['arm'],val(x['mean_gain']),str(x['positive_cases'])+'/4',str(x['eligible']),str(x['general_evidence'])])+'|')
 extra+=['','最终组合核验：`'+json.dumps(sel['combo_check'],ensure_ascii=False)+'`。没有满足3/4改善时，应解释为MIXED/探索性相对较好方案，不能称已证明通用改善。','', '[G03九个隔离对照](figures/full/G03_Eight_Isolated_Controls.png) · [固定分母全部试跑指标](metrics/ALL_ARM_FIT_COMPARISON.csv) · [保存阶段漏覆盖变化](metrics/SAVED_STAGE_FAR_COVERAGE.csv)','', '原0.25D上限与早期停滞是两件事：输入曲面到部分漏覆盖射线的必要位移下界最高7.192mm，超过4.778mm上限；但012从未接近该上限。O4未到上限时的路径差不能归因为上限改善。独立重复的FP32光栅/离散射线分支误差必须与小幅收益一起解释。','', 'O3N局部归一化能产生更大位移，但更大位移不等于正确柄部。必须同时检查真实Mask漏覆盖、头部误扩、侧视连续性、GT到预测的完整距离和最低点/高度跨度。Dxy/Hmax单项接近不能抵消缺柄。']
 lines+=extra
 (R/'TECHNICAL_REPORT.md').write_text('\n'.join(lines)+'\n')
 failures=['# 失败与异常台账','','不删除失败、不把低损失视为几何正确。全部11例保留同一数据和观察方向。','', '前期工程异常：新增初始化配置最初缺少depth字段，尚未发生优化更新即报错；补齐相同012配置后重跑，原失败日志保留runtime/NEW_FIT_G10.log和G11.log。不存在以此更换病例。','']
 for c,run in zip(cases,runs):
  n=c['name'];h=load(R/'metrics'/(n+'_TRAINING.json'));cand=load(R/'metrics'/(n+'_CANDIDATES.json'));co=Counter(reason for t in cand for reason in t['reasons']);g=by[n,'FINAL013'];r=gg.get((n,'FINAL013'),{});failures +=['## '+n,'',f"{run['status']}，{run['accepted']}/{run['attempts']}接受；最大累计位移{run['maximum_displacement_mm']:.6g}mm。拒绝原因计数：{dict(co)}。",f"独立几何：Ring相交={g['Ring_surface_collision']}，采样穿透={g['Ring_signed_sample_penetration_mm']:.6g}mm，非流形边={g['nonmanifold_edge_N']}，退化面={g['degenerate_F_N']}。严格体积IoU：{r.get('IoU_3D_status','NOT_EVALUABLE')}。",f"[原坐标完整图](figures/full/{n}_Native_Detail.png) · [纯主体六视图](figures/full/{n}_Body_Six_Views.png)。原始日志与全部拒绝候选：arms/FINAL_UNIFORM/metrics/{n}_CANDIDATES.json。",'']
 (R/'FAILURE_LEDGER.md').write_text('\n'.join(failures))
 index=['# 完整结果索引','','大模型、原始RGB/Mask/HERO/视频/GT均不提交GitHub；以下本地路径与SHA索引供恢复。','',f'运行根：`{R}`','', '关键图：figures/Fig1–Fig4；逐例详图：figures/full/；全部方法配置：config/PROTOCOL.json；最终选择：config/SELECTED_FINAL.json。','', '预测：local_results/G*/FINAL.npz（真实毫米顶点、原始面身份与底盖标签）、FINAL.pt（参数、优化器、随机状态和配置）；各接受里程碑同目录。','', '全部试跑：arms/PILOT_A*/、PILOT_O*/、COMBINED_VERIFY/；完整012重现：arms/REPLAY_012_FULL/；正式统一：arms/FINAL_UNIFORM/。','', '公制预测：local_results/metric/G*/FINAL011/012/013.npz；纯主体刚性对齐：local_results/aligned/G*/FINAL*.npz；T/最优与次优：metrics/BLENDER_RIGID_ALIGNMENT.json及metrics/alignment/；GT独立来源：evaluation_only/GT_SOURCE_LOCK.json。','', '新输入：new_input_pipeline/G10/groups/G10、G11/groups/G11；来源、帧和相机SHA：assets_index/与inputs/G*/CASE.json。','', '指标：metrics/NATIVE_SUMMARY.csv、PER_VIEW_METRICS.csv、BLENDER_GEOMETRIC_METRICS.csv、PAIRED_012_013.csv。历史冻结：assets_index/HISTORY_012_PROTECTION.json。']
 (R/'RESULT_INDEX.md').write_text('\n'.join(index)+'\n')
 print('REPORT_WRITTEN',N,G)
if __name__=='__main__':main()
